package org.example.spotifymixer.ui;

import android.app.Activity;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;

/** The concept's modal surface and compact, resource-independent controls. */
public final class EnhancerPanel {
    public static final int BG=0xff101314,CARD=0xff1c2022,LINE=0xff353b3e,GREEN=0xff1ed760,WHITE=0xfff4f6f5,MUTED=0xffa6afb2;
    private EnhancerPanel(){}
    public static int dp(android.content.Context c,int n){return EnhancerTheme.dp(c,n);}
    public static GradientDrawable surface(int color,int radius,android.content.Context c,boolean border){GradientDrawable out=EnhancerTheme.surface(color,radius,c);if(border)out.setStroke(dp(c,1),LINE);return out;}
    public static TextView label(LinearLayout box,String value,int size,int color,boolean bold){TextView t=new TextView(box.getContext());t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setIncludeFontPadding(false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(box.getContext(),6);lp.bottomMargin=dp(box.getContext(),6);box.addView(t,lp);return t;}
    public static Button button(LinearLayout box,String label,boolean primary,Runnable action){Button b=new Button(box.getContext());b.setText(label);b.setAllCaps(false);b.setSingleLine(true);b.setEllipsize(android.text.TextUtils.TruncateAt.END);b.setTextSize(14);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{0xff737b78,primary?0xff07150c:WHITE}));b.setPadding(dp(box.getContext(),14),0,dp(box.getContext(),14),0);b.setMinimumHeight(0);b.setMinHeight(0);b.setElevation(0);b.setStateListAnimator(null);StateListDrawable states=new StateListDrawable();states.addState(new int[]{-android.R.attr.state_enabled},surface(0xff292e2b,primary?28:12,box.getContext(),false));states.addState(new int[]{},surface(primary?GREEN:Color.TRANSPARENT,primary?28:12,box.getContext(),!primary));b.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(0x22ffffff),states,null));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(box.getContext(),primary?50:44));lp.topMargin=dp(box.getContext(),6);lp.bottomMargin=dp(box.getContext(),6);box.addView(b,lp);return b;}
    public static LinearLayout card(LinearLayout box){LinearLayout c=new LinearLayout(box.getContext());c.setOrientation(1);int pad=dp(c.getContext(),14);c.setPadding(pad,pad,pad,pad);GradientDrawable background=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{CARD,0xff171b1d});background.setCornerRadius(dp(c.getContext(),16));background.setStroke(dp(c.getContext(),1),LINE);c.setBackground(background);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(c.getContext(),6);lp.bottomMargin=dp(c.getContext(),6);box.addView(c,lp);return c;}
    public static ImageButton icon(android.content.Context c,String kind,String description,Runnable action){ImageButton b=new ImageButton(c);b.setImageDrawable(new EnhancerIcon(kind,WHITE));b.setContentDescription(description);b.setBackgroundColor(Color.TRANSPARENT);b.setPadding(dp(c,10),dp(c,10),dp(c,10),dp(c,10));b.setOnClickListener(v->action.run());return b;}
    public static LinearLayout page(Activity a,String title,boolean home,Runnable back,Runnable spotify){
        a.getWindow().setBackgroundDrawable(new ColorDrawable(Color.TRANSPARENT));a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attrs=a.getWindow().getAttributes();attrs.dimAmount=.64f;a.getWindow().setAttributes(attrs);a.getWindow().setStatusBarColor(0x00000000);a.getWindow().setNavigationBarColor(BG);
        FrameLayout shell=new FrameLayout(a);shell.setOnClickListener(v->spotify.run());
        LinearLayout panel=new LinearLayout(a);panel.setOrientation(1);panel.setBackground(surface(BG,24,a,true));panel.setClipToOutline(true);panel.setOnClickListener(v->{});
        FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(-1,-1,Gravity.BOTTOM);p.topMargin=dp(a,home?96:16);shell.addView(panel,p);
        shell.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});
        LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(a,10),dp(a,12),dp(a,14),dp(a,8));
        if(!home)header.addView(icon(a,"back","Back to SpotEnhancer",back),new LinearLayout.LayoutParams(dp(a,40),dp(a,40)));
        TextView heading=new TextView(a);heading.setText(home?"":title);heading.setTextSize(18);heading.setTextColor(WHITE);heading.setTypeface(Typeface.DEFAULT,Typeface.BOLD);header.addView(heading,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout actions=new LinearLayout(a);Button toSpotify=button(actions,"‹  Back to Spotify",false,spotify);toSpotify.setTextSize(11);LinearLayout.LayoutParams bp=(LinearLayout.LayoutParams)toSpotify.getLayoutParams();bp.height=dp(a,34);bp.width=dp(a,126);toSpotify.setLayoutParams(bp);header.addView(actions);
        if(home)header.addView(icon(a,"close","Close SpotEnhancer",spotify),new LinearLayout.LayoutParams(dp(a,40),dp(a,40)));
        panel.addView(header);ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.setClipToPadding(false);LinearLayout body=new LinearLayout(a);body.setOrientation(1);body.setPadding(dp(a,18),0,dp(a,18),dp(a,20));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));a.setContentView(shell);shell.requestApplyInsets();return body;
    }
    public static void feature(LinearLayout parent,String title,String subtitle,String icon,Runnable action){LinearLayout card=card(parent);card.setOrientation(0);card.setGravity(Gravity.CENTER_VERTICAL);card.setMinimumHeight(dp(parent.getContext(),76));ImageView mark=new ImageView(parent.getContext());mark.setImageDrawable(new EnhancerIcon(icon,icon.equals("mix")?GREEN:WHITE));card.addView(mark,new LinearLayout.LayoutParams(dp(parent.getContext(),28),dp(parent.getContext(),28)));LinearLayout copy=new LinearLayout(parent.getContext());copy.setOrientation(1);copy.setPadding(dp(parent.getContext(),18),0,dp(parent.getContext(),8),0);card.addView(copy,new LinearLayout.LayoutParams(0,-2,1));label(copy,title,16,WHITE,true);label(copy,subtitle,12,MUTED,false);ImageView chevron=new ImageView(parent.getContext());chevron.setImageDrawable(new EnhancerIcon("chevron",MUTED));card.addView(chevron,new LinearLayout.LayoutParams(dp(parent.getContext(),20),dp(parent.getContext(),20)));card.setContentDescription(title);card.setOnClickListener(v->action.run());card.setFocusable(true);}
}
